"""Select final designs, post-process every reported value, run independent checks."""
import math, json, pickle, copy, sys
import numpy as np
from optimize import *

CHOSEN_D = {'CR-P1': 45.0, 'CR-P2': 45.0, 'CR-P3': 45.0, 'CR-P4': 42.0, 'CR-P5': 42.0, 'CR-P6': 45.0}
WALL_LS = [288., 300., 312., 324., 336., 348., 360.]


def ceil_to(v, nd):
    f = 10 ** nd
    return math.ceil(v * f - 1e-9) / f


def floor_to(v, nd):
    f = 10 ** nd
    return math.floor(v * f + 1e-9) / f


def evaluate(pad, tag, D_in, B_in, L_in, t_in, ftype, n=0, Ht=0, qdef='mine'):
    """Independent re-evaluation of one foundation (used for checks and reduction tests)."""
    D = D_in / 12.0; B = B_in / 12.0; L = L_in / 12.0; t = t_in / 12.0
    x = STATION[tag]
    P = REACT[pad][tag]['SERVICE_D_PLUS_L'][0]
    if qdef == 'mine':
        q = P / (B * L) + (CONC_PCF / 1000.0 - GAMMA['I']) * t
    elif qdef == 'P/A':
        q = P / (B * L)
    else:  # gross
        q = P / (B * L) + CONC_PCF / 1000.0 * t + GAMMA['I'] * (D - t)
    qa, res, sig, g, st = q_allow_net(pad, x, D, B, L)
    out = dict(q=q, qa=qa, st=st, res=res)
    if ftype == 'SPREAD':
        out['s_mid'] = settlement(pad, x, D, B, L, q, 0.0, 'mid')
        out['s_split'] = settlement(pad, x, D, B, L, q, 0.0, 'split')
        out['qg'] = 0.0; out['Ra'] = 0.0
    else:
        Ra = n * PIER_AREA / (B * L)
        s1, suz, slz, qg = settlement_improved(pad, x, D, B, L, q, Ra, Ht, 'mid')
        s2 = settlement_improved(pad, x, D, B, L, q, Ra, Ht, 'split')[0]
        out.update(s_mid=s1, s_split=s2, suz=suz, slz=slz, qg=qg, Ra=Ra)
    return out


def design_pad(pad, D_in, mode='any', margin=0.01, s_lim=0.97):
    cl = []
    for tag in TAGS:
        c = gen_candidates(pad, tag, D_in, Bmax_ft=34.0, allow_imp=(mode != 'none'), s_lim=s_lim,
                           wall_L_opts=WALL_LS)
        if mode == 'all':
            c = [x for x in c if x['type'] == 'IMPROVED_SPREAD']
        # keep a small margin on bearing so that rounded reported values stay consistent
        c = [x for x in c if x['qnet'] <= x['qa'] - 0.002]
        cl.append(prune(c, 0.002))
    r = chain_dp(cl, margin=margin, imp_mode=('none' if mode == 'none' else 'any'))
    return r


def reduction_test(pad, D_in, des, i):
    """Return list of constraints violated when foundation i loses one 3-in step of width."""
    c = des[i]
    tag = c['tag']
    viol = set()
    conc = concrete_for_pad(pad)
    Pu = REACT[pad][tag]['STRENGTH_1.2D_1.6L'][0]
    wall = tag == 'W1'
    trials = []
    if wall:
        trials.append((c['B_in'] - 3, c['L_in']))
        if c['L_in'] - 3 >= WALL_L_FT * 12:
            trials.append((c['B_in'], c['L_in'] - 3))
    else:
        trials.append((c['B_in'] - 3, c['L_in'] - 3))
    for (Bn, Ln) in trials:
        if (not wall and Bn < 24) or (wall and Bn < 20):
            viol.add('MIN_WIDTH'); continue
        c1, c2 = (WALL_T_IN, WALL_L_FT * 12) if wall else (COL_IN[tag], COL_IN[tag])
        tn = thickness_req(Pu, Bn, Ln, c1, c2, conc['fc'])
        if wall:
            tn = max(tn, c['t_in'])
        if tn is None or tn > D_in - 3:
            viol.add('PUNCHING_SHEAR')
            tn = c['t_in']
        e = evaluate(pad, tag, D_in, Bn, Ln, tn, c['type'], c['n'], c['Ht'])
        if e['q'] > e['qa']:
            viol.add('BEARING')
        if max(e['s_mid'], e['s_split']) > TS_LIMIT_IN:
            viol.add('SETTLEMENT')
        for j in (i - 1, i + 1):
            if 0 <= j < len(des):
                o = des[j]
                lim = abs(STATION[TAGS[j]] - STATION[tag]) * 12.0 * ANG_LIMIT
                if abs(e['s_mid'] - o['s']) > lim or abs(e['s_split'] - o['s_split']) > lim:
                    viol.add('ANGULAR_DISTORTION')
        if c['type'] == 'IMPROVED_SPREAD' and e['qg'] * 1000 > QG_MAX_PSF:
            viol.add('BEARING')
        if wall:
            stb = sliding_etc(pad, Bn / 12.0, Ln / 12.0, tn / 12.0, D_in / 12.0)
            if stb['fs_slide'] < FS_SLIDING:
                viol.add('SLIDING')
            if stb['e_rep_ft'] > min(Bn, Ln) / 12.0 / 6.0:
                viol.add('OVERTURNING')
            if stb['fs_uplift'] < FS_UPLIFT:
                viol.add('UPLIFT')
    return viol


PRIORITY = ['BEARING', 'SETTLEMENT', 'ANGULAR_DISTORTION', 'SLIDING', 'OVERTURNING', 'UPLIFT',
            'MIN_WIDTH', 'PUNCHING_SHEAR', 'FROST']


def governing_for(pad, D_in, des, i):
    c = des[i]
    v = reduction_test(pad, D_in, des, i)
    for p in PRIORITY:
        if p in v:
            return p, v
    # fall back to the constraint closest to its limit
    ratios = {'BEARING': c['qnet'] / c['qa'], 'SETTLEMENT': max(c['s'], c['s_split']) / TS_LIMIT_IN}
    return max(ratios, key=ratios.get), v


def pad_governing(pad, D_in, des, govs):
    # count binding constraints; prefer those that are also >= 80 % of limit on reported numbers
    cnt = {}
    for g in govs:
        cnt[g] = cnt.get(g, 0) + 1
    best = sorted(cnt.items(), key=lambda kv: (-kv[1], PRIORITY.index(kv[0])))[0][0]
    return best


if __name__ == '__main__':
    results = {}
    for pad in PADS:
        D_in = CHOSEN_D[pad]
        r = design_pad(pad, D_in, 'any')
        cost, des = r
        fx, days, imp = pad_fixed(pad, D_in, des)
        results[pad] = dict(D_in=D_in, cost=cost, fixed=fx, days=days, imp=imp, des=des)
        print(pad, D_in, round(cost + fx), ''.join('I' if c['type'] != 'SPREAD' else 'S' for c in des))
    pickle.dump(results, open('final_designs.pkl', 'wb'))

