"""Independent check of output/submission.zip (re-derives from the parameter file only)."""
import json, zipfile, math, io, re, sys
import openpyxl
sys.path.insert(0, '.')
import core as C

zp = '../output/submission.zip'
z = zipfile.ZipFile(zp)
names = sorted(z.namelist())
need = sorted(['foundation_geometry.json', 'ground_improvement_plan.json', 'foundation_schedule.xlsx',
               'foundation_feasibility_matrix.md', 'constraint_register.xlsx', 'design_basis.md'])
assert names == need, names
G = json.loads(z.read('foundation_geometry.json'))
GI = json.loads(z.read('ground_improvement_plan.json'))
DB = z.read('design_basis.md').decode()
errs = []; warns = []


def E(msg):
    errs.append(msg)


def W(msg):
    warns.append(msg)


def no_nulls(o, path=''):
    if o is None:
        E('null at ' + path)
    elif isinstance(o, dict):
        for k, v in o.items():
            no_nulls(v, path + '/' + str(k))
    elif isinstance(o, list):
        for i, v in enumerate(o):
            no_nulls(v, path + '/%d' % i)


no_nulls(G); no_nulls(GI)
assert DB.startswith('```json'), 'design basis must open with json block'
js = DB.split('```json', 1)[1].split('```', 1)[0]
DBJ = json.loads(js)

FIELDS = ['foundation_type', 'B_in', 'L_in', 'thickness_in', 'bearing_stratum', 'reinforcement_ratio', 'bar_size',
          'bar_spacing_in', 'q_net_ksf', 'q_allow_net_ksf', 'settlement_in', 'pier_count', 'pier_diameter_in',
          'pier_depth_ft', 'area_replacement_ratio', 'top_of_pier_stress_psf', 'governing_constraint']
VOC = {'BEARING', 'SETTLEMENT', 'ANGULAR_DISTORTION', 'MIN_WIDTH', 'SLIDING', 'OVERTURNING', 'UPLIFT', 'PUNCHING_SHEAR', 'FROST'}
PADF = ['bearing_depth_in', 'fs_bearing', 'occupancy_class', 'improved', 'sulfate_pct', 'sulfate_exposure_class',
        'exposure_classes', 'fc_psi', 'max_wcm', 'dewatering_days', 'governing_constraint', 'foundations']

total_cost = 0.0
sett = {}
for pad in C.PADS:
    P = G['pads'][pad]
    for f in PADF:
        if f not in P:
            E('%s missing %s' % (pad, f))
    D_in = P['bearing_depth_in']; D = D_in / 12.0
    if D_in % 3 != 0 or D_in < 42 or D_in > 180:
        E('%s bearing depth %s' % (pad, D_in))
    conc = C.concrete_for_pad(pad)
    if P['fc_psi'] != conc['fc'] or abs(P['max_wcm'] - conc['max_wcm']) > 1e-9 or P['sulfate_exposure_class'] != conc['sulfate_class']:
        E('%s concrete' % pad)
    if P['fs_bearing'] != C.FS_TABLE[C.OCC[pad]]:
        E('%s FS' % pad)
    if P['governing_constraint'] not in VOC:
        E('%s pad gov' % pad)
    fc = P['fc_psi']
    padcost = 0.0
    imp_any = False
    for tag in C.TAGS:
        F = P['foundations'][tag]
        for f in FIELDS:
            if f not in F:
                E('%s %s missing %s' % (pad, tag, f))
        if F['governing_constraint'] not in VOC:
            E('%s %s gov' % (pad, tag))
        B_in, L_in, t_in = F['B_in'], F['L_in'], F['thickness_in']
        for v in (B_in, L_in, t_in):
            if v % 3 != 0:
                E('%s %s not on 3 in grid' % (pad, tag))
        if t_in < 12:
            E('%s %s thin' % (pad, tag))
        B, L, t = B_in / 12, L_in / 12, t_in / 12
        x = C.STATION[tag]
        Psvc = C.REACT[pad][tag]['SERVICE_D_PLUS_L'][0]
        Pu = C.REACT[pad][tag]['STRENGTH_1.2D_1.6L'][0]
        wall = tag == 'W1'
        # min width
        if (not wall and min(B_in, L_in) < 24) or (wall and B_in < 20):
            E('%s %s min width' % (pad, tag))
        if wall and L_in < 288:
            W('%s W1 shorter than wall' % pad)
        # stratum
        st = C.stratum_at(pad, x, D + 1e-6)
        if st != F['bearing_stratum']:
            E('%s %s stratum %s vs %s' % (pad, tag, st, F['bearing_stratum']))
        # bearing
        qa, res, sig, g, st2 = C.q_allow_net(pad, x, D, B, L)
        q_mine = Psvc / (B * L) + 0.032 * t
        q_PA = Psvc / (B * L)
        if F['q_allow_net_ksf'] > qa * 1.0000001:
            E('%s %s q_allow reported > least-of-three' % (pad, tag))
        vesic = res['Vesic'] / C.FS_TABLE[C.OCC[pad]] - sig
        if F['q_allow_net_ksf'] > 1.06 * vesic:
            E('%s %s q_allow > 1.06 x Vesic' % (pad, tag))
        if q_mine > F['q_allow_net_ksf'] + 1e-9:
            E('%s %s bearing exceeded %.3f > %.3f' % (pad, tag, q_mine, F['q_allow_net_ksf']))
        if F['q_net_ksf'] < q_mine - 1e-6:
            E('%s %s reported q_net below recomputed' % (pad, tag))
        # settlement (independent implementation: loop)
        imp = F['foundation_type'] == 'IMPROVED_SPREAD'
        if imp:
            imp_any = True
            n = F['pier_count']; Ht = F['pier_depth_ft']
            if F['pier_diameter_in'] != 30:
                E('pier dia')
            Ra = n * math.pi * 1.25 ** 2 / (B * L)
            if Ra < 0.33 - 1e-9 or Ra > 0.4007:
                E('%s %s Ra %.4f' % (pad, tag, Ra))
            if abs(Ra - F['area_replacement_ratio']) > 2e-4:
                E('%s %s Ra reported %.4f vs %.4f' % (pad, tag, F['area_replacement_ratio'], Ra))
            if not (8 <= Ht <= 25) or Ht != int(Ht):
                E('%s %s treat depth' % (pad, tag))
            from optimize import piers_fit
            if n > piers_fit(B, L):
                E('%s %s piers do not fit' % (pad, tag))
        res_s = {}
        for qd, q in (('mine', q_mine), ('P/A', q_PA)):
            for mode in ('mid', 'split'):
                if imp:
                    qg = q * 10 / (10 * Ra - Ra + 1)
                    s = qg * 1000 / 144 / C.KG[pad] + C.settlement(pad, x, D, B, L, q, Ht, mode)
                else:
                    s = C.settlement(pad, x, D, B, L, q, 0.0, mode)
                res_s[(qd, mode)] = s
        smax = max(res_s.values())
        if smax > 1.0:
            E('%s %s settlement %.3f' % (pad, tag, smax))
        if F['settlement_in'] < res_s[('mine', 'mid')] - 1e-6:
            E('%s %s settlement reported low' % (pad, tag))
        if F['settlement_in'] > 1.0:
            E('%s %s settlement reported > 1' % (pad, tag))
        sett[(pad, tag)] = res_s
        if imp:
            qg_psf = q_mine * 10 / (10 * Ra - Ra + 1) * 1000
            if qg_psf > 18000:
                E('%s %s qg' % (pad, tag))
            if F['top_of_pier_stress_psf'] < qg_psf * 0.999:
                E('%s %s qg reported low' % (pad, tag))
        else:
            for f in ('pier_count', 'pier_diameter_in', 'pier_depth_ft', 'area_replacement_ratio', 'top_of_pier_stress_psf'):
                if F[f] != 0:
                    E('%s %s spread with pier field %s' % (pad, tag, f))
        # structural: shear with phi 0.85 and 0.75
        c1, c2 = (12.0, 288.0) if wall else (C.COL_IN[tag], C.COL_IN[tag])
        if not C.shear_ok(Pu, B_in, L_in, c1, c2, t_in, fc, 0.75):
            E('%s %s shear phi 0.75 fails' % (pad, tag))
        rho_req = C.flexure_rho(Pu, B_in, L_in, c1, c2, t_in, fc)
        rho_bar = C.BARS[F['bar_size']] * 12 / F['bar_spacing_in'] / (12 * t_in)
        if abs(rho_bar - F['reinforcement_ratio']) > 2e-6:
            E('%s %s bar ratio mismatch %.6f %.6f' % (pad, tag, rho_bar, F['reinforcement_ratio']))
        if F['reinforcement_ratio'] < max(0.0018, rho_req) - 1e-9:
            E('%s %s rho low' % (pad, tag))
        if F['bar_size'] < 4 or F['bar_spacing_in'] > 12:
            E('%s %s bar rules' % (pad, tag))
        if t_in > D_in:
            E('%s %s footing above grade' % (pad, tag))
        # W1 stability
        if wall:
            for f in ('sliding_fs', 'eccentricity_in', 'uplift_fs'):
                if f not in F:
                    E('W1 missing ' + f)
            r = C.REACT[pad]['W1']
            Wf = B * L * t * 0.150
            Ws = max(D - t, 0) * (B * L - 24.0) * 0.118
            N_alt = r['0.6D_PLUS_W'][0] + 0.6 * (Wf + Ws)
            N_con = N_alt + r['UPLIFT_W'][0]
            Kp = math.tan(math.radians(45 + 13)) ** 2
            Pp = B * (0.5 * Kp * 0.118 * (D ** 2 - (D - t) ** 2) + 2 * 0.25 * math.sqrt(Kp) * t)
            mu = math.tan(math.radians(26 * 2 / 3))
            fs_con = (N_con * mu + 0.5 * Pp) / r['0.6D_PLUS_W'][1]
            fs_nopass = (N_alt * mu) / r['0.6D_PLUS_W'][1]
            if fs_con < 2.0:
                E('%s sliding conservative %.2f' % (pad, fs_con))
            if fs_nopass < 2.0:
                W('%s sliding w/o passive (no uplift deduction) %.2f' % (pad, fs_nopass))
            if F['sliding_fs'] > fs_con * 1.2:
                E('sliding reported')
            Pw, Hw, Mw = r['SERVICE_D_PLUS_L_PLUS_W']
            e = (Mw + Hw * t) / (Pw + Wf + Ws)
